        short: "\u0645\u0648\u0648\u0633\u06B5",
        description: "\u0646\u0632\u06CC\u06A9\u06D5\u06CC \u0646\u06CC\u0648 \u0645\u0644\u06CC\u06C6\u0646 \u0698\u06D5\u0645 \u062E\u0648\u0627\u0631\u062F\u0646\u06CC \u06AF\u06D5\u0631\u0645 \u0644\u06D5 \u0633\u0627\u06B5\u06CC \u0662\u0660\u0662\u0662 \u062F\u0627\u0628\u06D5\u0634 \u06A9\u0631\u0627\u060C \u0661\u0660 \u06A9\u06D5\u0645\u067E \u0628\u06D5\u0695\u06CE\u0648\u06D5\u062F\u06D5\u0628\u0631\u0627\u0646\u060C \u0647\u06D5\u0631\u0648\u06D5\u0647\u0627 \u0646\u06D5\u062E\u06C6\u0634\u0627\u0646 \u0644\u06D5 \u06A9\u06D5\u0645\u067E\u06D5\u06A9\u0627\u0646\u06CC \u0695\u06C6\u0698\u0647\u06D5\u06B5\u0627\u062A\u06CC \u0645\u0648\u0633\u06B5 \u0628\u06C6 \u0646\u06D5\u062E\u06C6\u0634\u062E\u0627\u0646\u06D5\u06A9\u0627\u0646\u06CC \u0647\u06D5\u0648\u0644\u06CE\u0631 \u0648 \u0645\u0648\u0633\u06B5 \u06AF\u0648\u0627\u0633\u062A\u0631\u0627\u06CC\u06D5\u0648\u06D5.",
