        description: "\u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646\u06CC \u062E\u06C6\u0631\u0627\u06A9\u060C \u06CC\u0627\u0631\u0645\u06D5\u062A\u06CC \u06A9\u06D5\u0633\u0627\u0646\u06CC \u062E\u0627\u0648\u06D5\u0646 \u067E\u06CE\u062F\u0627\u0648\u06CC\u0633\u062A\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A \u0648 \u06CC\u0627\u0631\u0645\u06D5\u062A\u06CC \u062F\u0627\u0631\u0627\u06CC\u06CC \u0644\u06D5 \u06A9\u06D5\u0644\u0627\u0631\u060C \u06A9\u0641\u0631\u06CC\u060C \u062E\u0627\u0646\u06D5\u0642\u06CC\u0646\u060C \u0695\u0632\u06AF\u0627\u0631\u06CC \u0648 \u062F\u06D5\u0631\u0628\u06D5\u0646\u062F\u06CC\u062E\u0627\u0646 \u062C\u06CE\u0628\u06D5\u062C\u06CE \u06A9\u0631\u0627\u0646\u061B \u0647\u06D5\u0631\u0648\u06D5\u0647\u0627 \u0644\u06D5 \u0633\u0627\u06B5\u06CC \u0662\u0660\u0662\u0664\u062F\u0627 \u06CC\u0627\u0631\u0645\u06D5\u062A\u06CC \u0628\u06C6 \u062E\u06CE\u0632\u0627\u0646\u06D5 \u0632\u06CC\u0627\u0646\u0644\u06CE\u06A9\u06D5\u0648\u062A\u0648\u0648\u06D5\u06A9\u0627\u0646\u06CC \u0644\u0627\u0641\u0627\u0648 \u062F\u0627\u0628\u06D5\u0634 \u06A9\u0631\u0627.",
        explore: "\u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646 \u0628\u0628\u06CC\u0646\u06D5"
