        short: "\u0647\u06D5\u06B5\u06D5\u0628\u062C\u06D5",
        description: "\u06CC\u0627\u0631\u0645\u06D5\u062A\u06CC \u067E\u0632\u06CC\u0634\u06A9\u06CC \u06A9\u06C6\u06A4\u06CC\u062F-\u0661\u0669 \u0628\u06C6 \u0628\u06D5\u0695\u06CE\u0648\u06D5\u0628\u06D5\u0631\u0627\u06CC\u06D5\u062A\u06CC \u062A\u06D5\u0646\u062F\u0631\u0648\u0633\u062A\u06CC \u062F\u0627\u0628\u06CC\u0646 \u06A9\u0631\u0627\u061B \u0661\u0661 \u0642\u0648\u062A\u0627\u0628\u062E\u0627\u0646\u06D5 \u0646\u06C6\u0698\u06D5\u0646 \u06A9\u0631\u0627\u0646\u06D5\u0648\u06D5\u061B \u0644\u06D5 \u0633\u0627\u06B5\u06CC \u0662\u0660\u0662\u0663 \u0628\u0627\u062E\u0686\u06D5\u06CC\u06D5\u06A9\u06CC \u0645\u0646\u062F\u0627\u06B5\u0627\u0646 \u06A9\u0631\u0627\u06CC\u06D5\u0648\u06D5\u061B \u0647\u06D5\u0631\u0648\u06D5\u0647\u0627 \u06CC\u0627\u0631\u0645\u06D5\u062A\u06CC \u0648 \u067E\u0634\u062A\u06AF\u06CC\u0631\u06CC \u062E\u06CE\u0632\u0627\u0646\u06D5\u06A9\u0627\u0646\u06CC \u0626\u0627\u0632\u06CC\u0632\u0627\u0646 \u0628\u06D5\u0631\u062F\u06D5\u0648\u0627\u0645 \u0628\u0648\u0648.",
        explore: "\u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646 \u0628\u0628\u06CC\u0646\u06D5"
