        description: "\u06AF\u06D5\u0648\u0631\u06D5\u062A\u0631\u06CC\u0646 \u06A9\u0627\u0631\u06CC \u0626\u06CE\u0633\u062A\u0627\u06CC BCF \u0644\u06D5 \u062F\u06D5\u0631\u06D5\u0648\u06D5\u06CC \u0633\u0646\u0648\u0648\u0631 \u2014 \u0664\u0661\u0665 \u0628\u0627\u0631\u0647\u06D5\u06B5\u06AF\u0631\u060C \u0662\u0669\u066C\u0660\u0667\u0660 \u062E\u06CE\u0632\u0627\u0646\u060C \u0626\u0627\u0631\u062F \u0628\u06C6 \u0663\u066B\u0663\u0666 \u0645\u0644\u06CC\u06C6\u0646 \u0646\u0627\u0646\u060C \u06AF\u0627\u0632\u06C6\u06CC\u0644\u060C \u062F\u06D5\u0631\u0645\u0627\u0646 \u0648 \u06A9\u0627\u0631 \u2014 \u0644\u06D5\u06AF\u06D5\u06B5 \u0628\u06D5\u0631\u0646\u0627\u0645\u06D5\u06CC \u0686\u06D5\u0633\u067E\u0627\u0648\u06CC \u0639\u06D5\u0641\u0631\u06CC\u0646: \u06A9\u0644\u06CC\u0646\u06CC\u06A9\u06CC \u06AF\u06D5\u0695\u06C6\u06A9\u060C \u0646\u0627\u0648\u06D5\u0646\u062F\u06CC \u06A9\u0648\u0644\u062A\u0648\u0648\u0631 \u0648 \u06AF\u06D5\u0634\u06D5\u067E\u06CE\u062F\u0627\u0646\u06CC \u0628\u0627\u0631\u0632\u0627\u0646\u06CC\u060C \u067E\u0634\u062A\u06AF\u06CC\u0631\u06CC \u062E\u0648\u06CE\u0646\u062F\u06A9\u0627\u0631\u0627\u0646 \u0648 \u0661\u0669\u0662 \u0626\u0627\u0632\u06CC\u0632\u0627\u0646\u06CC \u0633\u06D5\u0631\u067E\u06D5\u0631\u0634\u062A\u06CC\u06A9\u0631\u0627\u0648.",
        explore: "\u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646 \u0628\u0628\u06CC\u0646\u06D5"
